/**
 * Phase 30: Asset fingerprinting for CDN/cache busting.
 *
 * Reads the manifest.json generated by scripts/build-client.mjs and provides
 * helpers for URL rewriting and immutable cache headers on fingerprinted assets.
 */

import { existsSync, readFileSync, statSync } from "node:fs";
import { join, resolve, dirname, extname } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const ROOT = resolve(__dirname, "..");
const DIST_DIR = join(ROOT, "client", "dist");
const MANIFEST_PATH = join(DIST_DIR, "manifest.json");

let cachedManifest = null;
let manifestMtime = 0;

/**
 * Read and cache the client/dist/manifest.json.
 * Reloads if the file has been modified since last read.
 *
 * @returns {Record<string, string>} Map of filename -> content hash
 */
export function getAssetManifest() {
  try {
    if (!existsSync(MANIFEST_PATH)) {
      return {};
    }

    const stat = statSync(MANIFEST_PATH);
    if (cachedManifest && stat.mtimeMs === manifestMtime) {
      return cachedManifest;
    }

    const raw = readFileSync(MANIFEST_PATH, "utf8");
    cachedManifest = JSON.parse(raw);
    manifestMtime = stat.mtimeMs;
    return cachedManifest;
  } catch {
    return {};
  }
}

/**
 * Get the fingerprinted URL for a client asset.
 *
 * Given "modules.js" and a manifest entry { "modules.js": "abc123def456" },
 * returns "/dist/modules.js?v=abc123def456".
 *
 * @param {string} filename - Original asset filename (e.g. "modules.js")
 * @returns {string} URL path with cache-busting query string
 */
export function assetUrl(filename) {
  const manifest = getAssetManifest();
  const hash = manifest[filename];
  if (hash) {
    return `/dist/${filename}?v=${hash}`;
  }
  return `/dist/${filename}`;
}

/**
 * Express middleware that sets aggressive cache headers for fingerprinted assets.
 *
 * Assets requested with a ?v= query parameter get Cache-Control: public, max-age=31536000, immutable.
 * Assets without a version query get standard caching with ETag/Last-Modified.
 *
 * @returns {import('express').RequestHandler}
 */
export function assetMiddleware() {
  return (req, res, next) => {
    // Only handle requests to /dist/
    if (!req.path.startsWith("/dist/")) {
      return next();
    }

    const hasVersion = req.query.v;

    if (hasVersion) {
      // Fingerprinted asset: cache forever (immutable)
      res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
      res.removeHeader("Pragma");
    } else {
      // Non-fingerprinted asset: short cache with revalidation
      res.setHeader("Cache-Control", "public, max-age=300, must-revalidate");
    }

    // Set appropriate content type hints
    const ext = extname(req.path);
    if (ext === ".js") {
      res.setHeader("X-Content-Type-Options", "nosniff");
    }

    next();
  };
}

/**
 * Generate a <script> tag with fingerprinted src.
 * @param {string} filename
 * @param {object} [attrs] - Additional attributes
 * @returns {string} HTML script tag
 */
export function scriptTag(filename, attrs = {}) {
  const url = assetUrl(filename);
  const extra = Object.entries(attrs)
    .map(([k, v]) => v === true ? k : `${k}="${v}"`)
    .join(" ");
  return `<script src="${url}"${extra ? " " + extra : ""}></script>`;
}

/**
 * Invalidate the cached manifest, forcing a reload on next access.
 */
export function invalidateManifestCache() {
  cachedManifest = null;
  manifestMtime = 0;
}
